// EXTRACT CHAT DATA
// Daten kommen als JSON Body von Next.js API

const input = $input.first().json;
const body = input.body || input;

// User ID (Clerk User ID, z.B. "user_2abc...")
const userId = body.user_id;
if (!userId) {
  throw new Error('user_id ist erforderlich');
}

// Message
const message = body.message;
if (!message || !message.trim()) {
  throw new Error('message ist erforderlich');
}

// Chat ID (von Supabase, für Nachrichten-Speicherung)
const chatId = body.chat_id || null;

// Session ID (für Chat-Memory)
const sessionId = body.sessionId || `session-${Date.now()}`;

// Chat History (letzte Nachrichten für Kontext)
const chatHistory = body.chatHistory || [];

// Historie formatieren für System-Prompt
let historyText = 'Keine vorherigen Nachrichten.';
if (chatHistory.length > 0) {
  historyText = chatHistory
    .slice(-10)
    .map(h => `[${h.role}]: ${h.content}`)
    .join('\n');
}

return {
  json: {
    user_id: userId,
    chat_id: chatId,
    session_id: sessionId,
    message: message.trim(),
    history_text: historyText,
    history_count: chatHistory.length
  }
};

// FORMAT OUTPUT
const input = $input.first().json;
const extractedData = $('Extract Chat Data').item.json;

// Output aus verschiedenen möglichen Formaten extrahieren
let output = input.output 
  || input.text 
  || input.message?.content 
  || input.response 
  || 'Entschuldigung, ich konnte keine Antwort generieren.';

output = output.trim();

return {
  json: {
    output: output,
    user_id: extractedData.user_id,
    chat_id: extractedData.chat_id,
    session_id: extractedData.session_id
  }
};
